/**
 * The constraint classes against the corpus, with no solver (CC-30 to CC-33 of the constraint-classes plan).
 *
 * The facts the maturity rubric reads are committed (`src/semantics/smt/class-facts.ts`, generated by
 * `scripts/measure-classes.ts`). This file recounts the cheap ones from what the repository holds (the
 * published examples, the L8 models and goldens, v9) and holds the committed levels to the recount; the
 * differential table is recounted by `npm run census:classes -- --check --strict`, in the per-commit gate and
 * in CI, because it reads about 700 probes.
 *
 * - CC-30: no committed level is above the level the recounted facts give. A hand-raised fact, or a test that
 *   was renamed away, fails here.
 * - CC-31: the partition adds up: every worklist row is counted once, in exactly one primary cell, and has one
 *   reading unless it is a no-clause row (a negative control drops a row).
 * - CC-32: the logic line a row alone gets is the logic its shape stands for (the census's own invariants).
 * - CC-33: the gate's `nonlinear` flag implies a nonlinear shape; the converse is false.
 */
import { describe, it, expect, beforeAll } from 'vitest';
import { obligationsOf } from '@semantics/obligations';
import { CLASS_FACTS } from '@semantics/smt/class-facts';
import { CELLS, classifyRow, levelOf, staticCensus, type ClassFacts } from '@semantics/smt/classes';
import { censusModel, invariantsHold, newCensus } from '../../scripts/lib/class-census';
import { compareLevels, computeFacts, factsCorpus, loadAt, z3Release, type LiveFacts } from '../../scripts/lib/class-facts';

const ROOT = process.cwd();
const sum = (r: Record<string, number>): number => Object.values(r).reduce((a, b) => a + b, 0);

let live: LiveFacts;
beforeAll(async () => {
  live = await computeFacts({ root: ROOT, full: false, table: false });
}, 900_000);

describe('CC-30: no committed level is above the recounted one', () => {
  it('holds the committed facts to a recount of the cheap ones (tests, goldens, defects), at the installed z3', () => {
    expect(live.unmatchedGoldens).toEqual([]);
    expect(live.notes).toEqual([]);
    expect(compareLevels(CLASS_FACTS, live.facts, 'cheap', { z3: z3Release(ROOT) })).toEqual([]);
  });

  it('is measured under the z3 this checkout installs', () => {
    expect(CLASS_FACTS.z3).toBe(z3Release(ROOT));
    expect(CLASS_FACTS.register).toBe(live.facts.register);
  });

  it('fails closed on a hand-raised fact, a vanished test and a dropped defect (negative controls)', () => {
    const z3 = z3Release(ROOT);
    // a fact raised by hand: the committed cell claims golden rows the recount does not find
    const raised: ClassFacts = {
      ...CLASS_FACTS,
      cells: { ...CLASS_FACTS.cells, 'nira/pinned': { ...CLASS_FACTS.cells['nira/pinned']!, goldenDecided: 5, tableAgree: 40, tableProbes: 6, encoderTests: 1 } },
    };
    expect(compareLevels(raised, live.facts, 'cheap', { z3 }).map((d) => d.cell)).toContain('nira/pinned');
    // a test that was renamed away: the register's pointer no longer resolves, so the recount has none
    const gone: ClassFacts = { ...live.facts, cells: { ...live.facts.cells, lra: { ...live.facts.cells.lra!, encoderTests: 0 } } };
    expect(compareLevels(CLASS_FACTS, gone, 'cheap', { z3 }).map((d) => d.cell)).toContain('lra');
    // an open wrong-verdict defect that is in the recount but not in the committed file
    const caps: ClassFacts = { ...live.facts, defects: [...live.facts.defects, { id: 'D-planted', todo: 'x', classes: ['lra'], kind: 'wrong-verdict', note: '' }] };
    expect(compareLevels(CLASS_FACTS, caps, 'cheap', { z3 }).map((d) => d.cell)).toContain('lra');
  });

  it('gives every cell a level and a cell no row stands in the level `experimental` at most', () => {
    for (const cell of CELLS) {
      const level = levelOf(cell, { facts: CLASS_FACTS, z3: z3Release(ROOT) });
      expect(level, cell).toBeTruthy();
      if ((CLASS_FACTS.cells[cell]?.rows ?? 0) === 0 && !cell.startsWith('fence/')) expect(['experimental', 'tested'], cell).toContain(level);
    }
  });
});

describe('CC-31 to CC-33: the partition over the examples, the L8 models and v9', () => {
  it('counts every row once, gives it one reading or the no-clause fence, and keeps the encoder’s own logic per shape', async () => {
    const census = newCensus(false);
    let models = 0;
    let rowsTotal = 0;
    let gateNonlinear = 0;
    for (const item of factsCorpus(ROOT, false)) {
      const model = await loadAt(item.path);
      if (!model) continue;
      models += 1;
      const rows = obligationsOf(model);
      rowsTotal += rows.length;
      // CC-31: the cells add up to the worklist, once each
      const counted = staticCensus(model, rows);
      expect(sum(counted.cells), item.name).toBe(rows.length);
      expect(sum(counted.readings), item.name).toBe(rows.filter((r) => r.source !== 'none').length);
      for (const r of rows) {
        const c = classifyRow(r, { model });
        expect((c.shape === null) === (c.fence !== null), `${item.name}: ${r.expression} is a shape or a fence, not both and not neither`).toBe(true);
        expect(c.reading === null, `${item.name}: ${r.expression}`).toBe(r.source === 'none');
        // CC-33: the gate's flag implies a nonlinear shape
        if (r.nonlinear && c.shape !== null) {
          gateNonlinear += 1;
          expect(['nra-poly', 'nra-div', 'nira'], `${item.name}: ${r.expression}`).toContain(c.shape);
        }
      }
      // negative control: a census that lost a row does not add up
      if (rows.length > 1) expect(sum(staticCensus(model, rows.slice(1)).cells)).toBe(rows.length - 1);
      censusModel(census, { corpus: item.corpus, name: item.name, model });
    }
    expect(models).toBeGreaterThan(70);
    expect(rowsTotal).toBeGreaterThan(500);
    expect(gateNonlinear).toBeGreaterThan(0);
    // CC-32: the census's own invariants (partition, totals, shape-to-logic, footprint against the engine)
    expect(census.checks, JSON.stringify(census.notes)).toEqual({});
    expect(invariantsHold(census)).toBe(true);
    for (const [k] of Object.entries(census.logics)) expect(k.split('\t')).toHaveLength(2);
  }, 900_000);

  it('detects a broken invariant (negative control for the census check)', () => {
    const census = newCensus(false);
    census.checks['totals: tallied rows differ from obligationsOf'] = 1;
    expect(invariantsHold(census)).toBe(false);
    const split = newCensus(false);
    split.logics['lra\tQF_LRA'] = 1;
    split.logics['lra\tQF_NRA'] = 1;
    expect(invariantsHold(split)).toBe(false);
  });
});
